using UnityEngine;
using UnityEditor;

public class CreateCookingAssets
{
    public static string Main()
    {
        string folder = "Assets/Herbal";
        int created = 0;

        // === 1. Buat 6 InventoryItem untuk hasil masakan ===
        string[][] cookedItems = new string[][] {
            new string[] { "Jamu Jahe", "Jamu jahe hangat, memulihkan tenaga." },
            new string[] { "Jamu Kunyit", "Jamu kunyit segar, menyehatkan badan." },
            new string[] { "Jamu Kencur", "Jamu kencur tradisional, penghilang pegal." },
            new string[] { "Jamu Temulawak", "Jamu temulawak, meningkatkan stamina." },
            new string[] { "Wedang Jahe", "Wedang jahe dengan kayu manis, sangat menghangatkan." },
            new string[] { "Jamu Beras Kencur", "Jamu beras kencur campuran herbal, sangat berkhasiat." }
        };

        foreach (var item in cookedItems)
        {
            string path = folder + "/" + item[0] + ".asset";
            if (AssetDatabase.LoadAssetAtPath<InventoryItem>(path) != null)
            {
                Debug.Log("[CreateAssets] Skip (sudah ada): " + path);
                continue;
            }

            var inv = ScriptableObject.CreateInstance<InventoryItem>();
            inv.itemName = item[0];
            inv.description = item[1];
            inv.itemType = InventoryItem.ItemType.Cooked;
            inv.icon = null;

            AssetDatabase.CreateAsset(inv, path);
            created++;
            Debug.Log("[CreateAssets] Dibuat: " + path);
        }

        // === 2. Load semua herb InventoryItem untuk referensi ingredient ===
        var jaheItem = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Jahe.asset");
        var kunyitItem = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Kunyit.asset");
        var kencurItem = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Kencur.asset");
        var temulawakItem = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Temulawak.asset");
        var kayuManisItem = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Kayu Manis.asset");
        var lengkuasItem = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Lengkuas.asset");

        // === 3. Load cooked InventoryItem untuk resultItem ===
        var jamuJahe = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Jamu Jahe.asset");
        var jamuKunyit = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Jamu Kunyit.asset");
        var jamuKencur = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Jamu Kencur.asset");
        var jamuTemulawak = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Jamu Temulawak.asset");
        var wedangJahe = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Wedang Jahe.asset");
        var jamuBerasKencur = AssetDatabase.LoadAssetAtPath<InventoryItem>(folder + "/Jamu Beras Kencur.asset");

        // === 4. Buat 6 CookingRecipe ===
        string recipeFolder = "Assets/Herbal/Recipes";
        if (!AssetDatabase.IsValidFolder(recipeFolder))
            AssetDatabase.CreateFolder(folder, "Recipes");

        // Helper: create ingredient
        System.Func<string, Sprite, int, CookingRecipe.Ingredient> makeIng = (name, icon, amt) => {
            var ing = new CookingRecipe.Ingredient();
            ing.itemName = name;
            ing.itemIcon = icon;
            ing.amountRequired = amt;
            return ing;
        };

        // Recipe 1: Jamu Jahe
        CreateRecipe(recipeFolder, "Jamu Jahe", "Jamu jahe hangat, memulihkan tenaga.", 20, jamuJahe,
            new CookingRecipe.Ingredient[] {
                makeIng("Jahe", jaheItem?.icon, 2)
            });
        created++;

        // Recipe 2: Jamu Kunyit
        CreateRecipe(recipeFolder, "Jamu Kunyit", "Jamu kunyit segar, menyehatkan badan.", 20, jamuKunyit,
            new CookingRecipe.Ingredient[] {
                makeIng("Kunyit", kunyitItem?.icon, 2)
            });
        created++;

        // Recipe 3: Jamu Kencur
        CreateRecipe(recipeFolder, "Jamu Kencur", "Jamu kencur tradisional, penghilang pegal.", 20, jamuKencur,
            new CookingRecipe.Ingredient[] {
                makeIng("Kencur", kencurItem?.icon, 2)
            });
        created++;

        // Recipe 4: Jamu Temulawak
        CreateRecipe(recipeFolder, "Jamu Temulawak", "Jamu temulawak, meningkatkan stamina.", 25, jamuTemulawak,
            new CookingRecipe.Ingredient[] {
                makeIng("Temulawak", temulawakItem?.icon, 2)
            });
        created++;

        // Recipe 5: Wedang Jahe
        CreateRecipe(recipeFolder, "Wedang Jahe", "Wedang jahe dengan kayu manis, sangat menghangatkan.", 35, wedangJahe,
            new CookingRecipe.Ingredient[] {
                makeIng("Jahe", jaheItem?.icon, 2),
                makeIng("Kayu Manis", kayuManisItem?.icon, 1)
            });
        created++;

        // Recipe 6: Jamu Beras Kencur
        CreateRecipe(recipeFolder, "Jamu Beras Kencur", "Jamu beras kencur campuran herbal, sangat berkhasiat.", 40, jamuBerasKencur,
            new CookingRecipe.Ingredient[] {
                makeIng("Kencur", kencurItem?.icon, 2),
                makeIng("Jahe", jaheItem?.icon, 1),
                makeIng("Kunyit", kunyitItem?.icon, 1)
            });
        created++;

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();

        return "Selesai! " + created + " asset dibuat.";
    }

    static void CreateRecipe(string folder, string name, string desc, int hp, InventoryItem resultItem, CookingRecipe.Ingredient[] ingredients)
    {
        string path = folder + "/" + name + ".asset";
        if (AssetDatabase.LoadAssetAtPath<CookingRecipe>(path) != null)
        {
            Debug.Log("[CreateAssets] Skip recipe (sudah ada): " + path);
            return;
        }

        var recipe = ScriptableObject.CreateInstance<CookingRecipe>();
        recipe.recipeName = name;
        recipe.description = desc;
        recipe.hpRestore = hp;
        recipe.resultItem = resultItem;
        recipe.ingredients = ingredients;
        recipe.recipeImage = resultItem?.icon;

        AssetDatabase.CreateAsset(recipe, path);
        Debug.Log("[CreateAssets] Dibuat recipe: " + path);
    }
}
